          "content": "<div class=\"row mt-5 d-sm-none d-md-block\">\n        \t\t\t\t\t\t\t\t\n        \t\t\t\t\t\t\t\t<div id=\"immn\" class=\"col-lg-5 float-start\"><div id=\"iwmw\"><ul id=\"ioo2\" class=\"iconlist iconlist-color m-0\"><h1 id=\"izb38\" class=\"abttitle mb-5 d-sm-none d-md-block\">How It Works</h1><li id=\"indw1\" class=\"mb-3 fs-40\"><i   class=\"icon-circle2 iv\"></i><div id=\"ilrqh\"><div id=\"itt3l\"><div id=\"inlpk\">Programs are available online & offline.</div></div></div></li><li id=\"iu5zk9\" class=\"mb-3 fs-40\"><i   class=\"icon-circle2 iv\"></i><div id=\"ijgeu\"><div id=\"i8jj7\"><div id=\"imjrb\">Free registration for all participants.</div></div></div></li><li id=\"i0bnml\" class=\"mb-3 fs-40\"><i   id=\"iscyox\" class=\"icon-circle2 iv\"></i><div id=\"imiy9r\"><div id=\"ikgdri\"><div id=\"inqjv4\"><span id=\"i5kxg8-2\">Scan the QR code or visit: </span><a href=\"https://wellness.bhaktivedantahospital.com/wellness/welcome\" target=\"_blank\"  id=\"ieao9f-2\">https://wellness.<wbr/>bhaktivedantahospital.com/<wbr/>wellness/welcome</a></div></div></div></li><li id=\"ilw7sg\" class=\"mb-3 fs-40\"><i  id=\"i6z38\" class=\"icon-circle2 iv\"></i><div id=\"igy9xl\"><div id=\"iscd5i\"><div id=\"iogpn\"><span>O</span><span id=\"i1b1dy\">nce registered, you will be connected via WhatsApp and guided through your chosen programs.</span></div></div></div></li></ul></div></div><div id=\"if2hdh\" class=\"col-lg-5 float-start\"><div id=\"ipb5r\"></div></div><section>",
