          "id": "t2",
          "title": "Services",
          "type": "rich_text",
          "content": "<div class=\"content-fluid container-bg mt-5 dkshow\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-6 dflex align-items-center\"><h1 class=\"color-white\">Home Visit Facility for Blood Sample Collection</h1></div><div id=\"imch\" class=\"col-lg-3\"><div class=\"white-box\"><p id=\"i1n5\">Available from <br/><span class=\"text-color-primary\">08:00 am to 07:00 pm within 10 km</span> <br/>radius of the Hospital at a nominal charge.</p></div></div><div id=\"ipbrt\" class=\"col-lg-3\"><div class=\"white-box\"><p id=\"iqt28\">To book a home visit,<br /> please call at <br /><span  class=\"text-color-primary\">07507128528/ <br />09325376911 / Blood Sample Collection, 8097527958 </span><div><span  class=\"text-color-primary\"> </span></div></p></div></div></div></div></div><div class=\"container-fluid\"><div class=\"container\"><div class=\"phshow mt-sm-2e\"><div id=\"ipgpt\" class=\"camps camps-sm valign-text-middle\"><span id=\"i0y5v\">Home Visit Facility for Blood Sample Collection,<div><span   class=\"text-color-primary\">8097527958</span></div></span></div><div class=\"fgpage1 mt-sm-1e\"><ul><li>Available from <br/><span class=\"text-color-primary\">08:00 am to 07:00 pm within 10 km</span> <br/>radius of the Hospital at a nominal charge.</li><li>To book a home visit,<br/> please call at <br/><span class=\"text-color-primary\">07507128528/ <br/>09325376911. </span></li></ul></div></div><div class=\"row mt-lg-5e\"><div class=\"col-lg-6 text-center dkshow\"><div class=\"fgpage-imgbg px-3 light-green-bg\"><img src=\"/images/diagnostic-routine.png\" class=\"amb_img\"/></div></div><div class=\"col-lg-6 mt-lg-2e ptb-sm-20 light-green-bg-sm\"><div class=\"camps camps-sm valign-text-middle\"><span><span>Routine Pathological Tests and Investigations</span> </span></div><div class=\"fgpage1 mt-sm-1e\"><ul><li>Hematology  </li><li>Clinical Pathology  </li><li>Serology </li><li>Biochemistry </li><li>Microbiology </li><li>Cytology </li><li>Histopathology </li></ul></div></div></div><div class=\"row mt-lg-5e mb-sm-1e\"><div class=\"col-lg-6 mt-lg-2e\"><div class=\"camps camps-sm valign-text-middle\"><span><span>Special Pathological Tests and Investigations</span> </span></div><div class=\"fgpage1 mt-sm-1e\"><ul><li>Radio Immunoassay Study</li><li>Drug Assay </li><li>Cancer Marker Study </li><li>Hormone Assay Study </li><li>Allergy Markers </li><li>Bone Marrow Aspiration and Cytology </li><li>Guided Biopsy </li></ul></div></div><div class=\"col-lg-6 text-center dkshow\"><div class=\"fgpage-imgbgr px-3\"><img src=\"/images/diagnostic-special.png\" class=\"amb_imgr\"/></div></div></div></div></div>\r\n        \t\t\t\t\t\t\t\t\t\r\n        \t\t\t\t\t\t\t\t</div>\r\n        \t\t\t\t\t\t\t        \t\t\t\t\t\t        \t\t\t\t\t\t\r\n\t\t\t\t\t\r\n\t\t\t\t</div>\r\n\t\t\t</div>\t\t\t\r\n\t\t</div>\r\n\t\t\t\r\n\t\t\t</div>",
