      "bannerImage": "https://ohaokdfkdafgpwccauos.supabase.co/storage/v1/object/public/services-images/rehabilitation/banner-rehabilitation.jpg",
      "thumbnailImage": "https://ohaokdfkdafgpwccauos.supabase.co/storage/v1/object/public/services-images/rehabilitation/thumbnail-rehabilitation.jpg",
      "slug": "/rehabilitation",
